/** fn facing (hop/physics.slg:59): the hero faces where the pad points, and keeps facing there when it lets go */
export function facing(pad: model.Pad, was: bigint): bigint {
  const dx = axis(pad.left, pad.right);
  const dz = axis(pad.forward, pad.back);
  if (dx === 1n) {
    return dz === -1n ? 45n : dz === 1n ? 315n : 0n;
  }
  if (dx === -1n) {
    return dz === -1n ? 135n : dz === 1n ? 225n : 180n;
  }
  return dz === -1n ? 90n : dz === 1n ? 270n : was;
}

/** fn slide_x (hop/physics.slg:69): move on one axis, then stop flush against the first solid in the way */
